-- Recompute statement balances from each current account balance and all newer
-- transactions. This preserves amounts while removing impossible negative
-- balances from the historical savings-account ledger.
UPDATE transactions AS current_tx
SET balance_after_minor = (
  SELECT accounts.balance_minor - COALESCE(SUM(newer.amount_minor), 0)
  FROM accounts
  LEFT JOIN transactions AS newer
    ON newer.account_id = current_tx.account_id
   AND newer.posted_at > current_tx.posted_at
  WHERE accounts.account_id = current_tx.account_id
);

